const b = $json.body || $json;
const slug = String(b.slug || '').trim();
const titulo = String(b.titulo || b.pdf?.titulo || '').trim();
if (!slug) return [{ json: { ok: false, error: 'falta slug' } }];
return [{ json: {
  ok: true, sistema: '10-vertice-pdf-upsell', etapa: 'brief_cursor', sin_api: true,
  brief: {
    proyecto: 'libros a entender / vertice',
    slug, titulo,
    prompt: `Generar o empaquetar PDF guía: ${titulo || slug}`,
    output: `data/${slug}/output/`
  },
  status: 'brief_listo',
  todo: 'SIN API: no llama Cursor aún. Después: HTTP/CLI al pipeline',
  at: new Date().toISOString()
}}];
